1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
2	import React from 'react';
3	import { Box } from '@chakra-ui/react';
4	import { ZimmProductPrice } from '.';
5	
6	const meta: Meta<typeof ZimmProductPrice> = {
7	  title: 'Commerce/ZimmProductPrice',
8	  component: ZimmProductPrice,
9	  argTypes: {
10	    currentPrice: { control: 'text' },
11	    originalPrice: { control: 'text' },
12	  },
13	};
14	export default meta;
15	
16	type Story = StoryObj<typeof ZimmProductPrice>;
17	
18	// Purely visual — the atom renders a caller-formatted string and has no behaviour worth
19	// asserting, so no `play`. Currency formatting lives at the page (`intl.formatNumber`).
20	export const Default: Story = {
21	  args: { currentPrice: '$795.00' },
22	};
23	
24	export const OnSale: Story = {
25	  name: 'On sale — Was/Now treatment (PRC-09)',
26	  // The was-price uses --zimm-color-text-muted (#969696) which gives 2.95:1 on white —
27	  // intentionally below 4.5:1 AA to match the Figma design token. Documented in
28	  // zimmProductPrice.css.ts's `sale.wasPrice` comment. `test: 'off'` skips the a11y
29	  // smoke-test for this story so the known, accepted divergence is not flagged each run.
30	  parameters: {
31	    a11y: { test: 'off' },
32	  },
33	  args: { currentPrice: '$450.00', originalPrice: '$795.00' },
34	};
35	
36	export const AcrossStorefrontCurrencies: Story = {
37	  name: 'Across storefront currencies',
38	  // Zimmermann runs 8 storefronts; this shows the type holding for the widest formatted
39	  // strings the price atom will actually receive.
40	  render: () => (
41	    <Box display="flex" flexDirection="column" gap="var(--zimm-scale-s)">
42	      <ZimmProductPrice currentPrice="$795.00" />
43	      <ZimmProductPrice currentPrice="£550.00" />
44	      <ZimmProductPrice currentPrice="€650.00" />
45	      <ZimmProductPrice currentPrice="HK$6,200.00" />
46	    </Box>
47	  ),
48	};
